const DEMO_PASSWORD = "Demo#2026";
// Conformément aux exigences de démonstration : un seul compte est préchargé (l'Administrateur système).
// Tous les autres comptes (Agences, DGSN, MINDEF, Voyageurs, RH, Analystes...) doivent être créés par lui
// depuis le module Utilisateurs, ce qui illustre concrètement le circuit mot de passe temporaire + droits par rôle.
export const ROLES_SYNSR = [
  "Employe RTC",
  "employe Agence",
  "Employe MINT",
  "Employe MINTRANS",
  "Employe MINDEF",
  "Employe SED",
  "Employe GEN",
  "Employe DGSN",
  "Citoyen",
];

export function deduireRoleSynsr(r) {
  if (!r) return "Citoyen";
  if (r.role && ROLES_SYNSR.includes(r.role)) return r.role;
  const p = (r.profil || "").toLowerCase();
  const nom = (r.nom || "").toLowerCase();
  if (p.includes("rtc") || p.includes("administrateur système") || nom.includes("patrick mballa")) return "Employe RTC";
  if (p.includes("agence") || p.includes("clientèle") || r.agence) return "employe Agence";
  if (p.includes("mintrans") || p.includes("mint")) return "Employe MINT";
  if (p.includes("mindef")) return "Employe MINDEF";
  if (p.includes("sed")) return "Employe SED";
  if (p.includes("gendarmerie") || p.includes("gen")) return "Employe GEN";
  if (p.includes("dgsn") || p.includes("police")) return "Employe DGSN";
  return "Citoyen";
}

