// Liste plate de communes dérivée de TERRITOIRE_CM, pour compatibilité avec le code existant.
const COMMUNES_SYNDEC = Object.values(TERRITOIRE_CM).flatMap((depts) => Object.values(depts).flat());
// Liste des régions du Cameroun, dérivée de TERRITOIRE_CM.
const REGIONS_SYNDEC = Object.keys(TERRITOIRE_CM);

// Code à deux lettres du centre d'état civil, dérivé de la région — utilisé comme préfixe
// du numéro de document, ex. CE202408250127-01 pour le Centre.
const REGION_CODE_CENTRE = {
  "Centre": "CE", "Littoral": "LT", "Ouest": "OU", "Nord-Ouest": "NO", "Sud-Ouest": "SO",
  "Nord": "NR", "Extrême-Nord": "EN", "Adamaoua": "AD", "Est": "ES", "Sud": "SU",
};
// Ancien mapping par nom de commune (données de démonstration historiques, avant l'intégration
// de la hiérarchie territoriale complète) — conservé pour la compatibilité.
const COMMUNE_CODE_CENTRE = {
  "Yaoundé 1er": "CE", "Douala 3e": "LT", "Bafoussam 1er": "OU", "Bamenda 2e": "NO", "Buea": "SO",
  "Garoua 1er": "NR", "Maroua 2e": "EN", "Ngaoundéré 1er": "AD", "Bertoua 1er": "ES", "Ebolowa": "SU",
};

// Génère un numéro de document officiel à partir de la région (préférée), ou à défaut de la
// commune, et de la référence du dossier — au même format que les certificats papier
// (préfixe centre + 9 chiffres + « -01 »).
function genererNumeroDocument(commune, reference, region) {
  const prefixe = REGION_CODE_CENTRE[region] || COMMUNE_CODE_CENTRE[commune] || "CE";
  const chiffres = String(reference).replace(/\D/g, "").padStart(9, "0").slice(-9);
  return `${prefixe}${chiffres}-01`;
}
// Génère un numéro d'inscription au registre, au même format que le fichier de référence
// (13 chiffres), dérivé de façon déterministe de la référence du dossier.
function genererNumeroInscription(reference) {
  const chiffres = String(reference).replace(/\D/g, "").padStart(7, "0").slice(-7);
  return `12022${chiffres}1`.slice(0, 13).padEnd(13, "0");
}

// Retire les préfixes administratifs (« Commune De », « Communauté Urbaine De »...) d'un nom
// de commune pour n'en garder que le nom propre, ex. « Commune D'Obala » → « Obala ».
function communeSimple(commune) {
  if (!commune) return "";
  return commune
    .replace(/^Communaute d'Arrondissement de\s+/i, "")
    .replace(/^Communaute Urbaine de\s+/i, "")
    .replace(/^Commune d'Arrondissement de\s+/i, "")
    .replace(/^Commune de la\s+/i, "")
    .replace(/^Commune du\s+/i, "")
    .replace(/^Commune de\s+/i, "")
    .replace(/^Commune d['’]/i, "")
    .replace(/^Commune\s+/i, "")
    .trim();
}
// Applique l'élision française (« de » → « d' ») devant une voyelle ou un H muet.
function avecElision(nom) {
  return /^[AEIOUHÀÉÈÊÎÔÛ]/i.test(nom) ? `d'${nom}` : `de ${nom}`;
}
// Construit le titre de l'autorité signataire en fonction de son rôle et de la commune
// du dossier, ex. « Le Maire d'Obala », « L'Officier d'état civil de Douala 3e ».
function titreOfficier(role, commune) {
  const lieu = avecElision(communeSimple(commune) || commune);
  switch (role) {
    case "Maire": return `Le Maire ${lieu}`;
    case "Adjoint au maire": return `L'Adjoint au maire ${lieu}`;
    case "Secrétaire d'état civil": return `Le Secrétaire d'état civil ${lieu}`;
    case "Officier d'état civil":
    default: return `L'Officier d'état civil ${lieu}`;
  }
}
// Sélectionne l'officier signataire d'un dossier : uniquement parmi les Maires/Officiers
// d'état civil réellement affectés à la commune du dossier (un officier ne pouvant traiter
// que les dossiers de sa propre commune d'attache — voir la gouvernance du module). Le choix
// entre plusieurs officiers éligibles reste déterministe (toujours le même pour un même
// dossier). À défaut d'officier affecté à cette commune, un profil générique est utilisé
// plutôt que d'afficher, à tort, une autorité d'une autre commune.
function officierPourDossier(agentsDisponibles, reference, commune) {
  const communeCible = communeSimple(commune) || commune;
  const eligibles = (agentsDisponibles || []).filter((a) => (communeSimple(a.commune) || a.commune) === communeCible);
  if (eligibles.length === 0) {
    return { nom: "Signataire non désigné", role: "Officier d'état civil" };
  }
  const chiffres = String(reference).replace(/\D/g, "") || "0";
  const index = Number(chiffres) % eligibles.length;
  return eligibles[index];
}

// Réduit une chaîne à de l'ASCII pur (accents retirés, tirets/guillemets typographiques
// remplacés) — certains lecteurs de QR Code et bibliothèques d'encodage interprètent mal les
// caractères non-ASCII, pouvant corrompre silencieusement le contenu au-delà du premier
// caractère spécial. Utilisé exclusivement pour le contenu embarqué dans le QR Code.
function versAsciiSur(texte) {
  return texte
    .normalize("NFD").replace(/[\u0300-\u036f]/g, "") // retire les accents (é -> e, à -> a...)
    .replace(/[—–]/g, "-")
    .replace(/['']/g, "'")
    .replace(/[""]/g, '"');
}

// Dessine une étoile pleine à 5 branches centrée en (cx, cy), de rayon externe `rayon`,
// dans la couleur RVB fournie — utilisé pour l'étoile du drapeau, qu'aucune police standard
// de jsPDF ne peut afficher correctement en tant que caractère unicode.
function dessinerEtoile(doc, cx, cy, rayon, r, g, b) {
  const points = [];
  const rayonInterne = rayon * 0.38;
  for (let i = 0; i < 10; i++) {
    const angle = (Math.PI / 5) * i - Math.PI / 2;
    const rad = i % 2 === 0 ? rayon : rayonInterne;
    points.push([cx + rad * Math.cos(angle), cy + rad * Math.sin(angle)]);
  }
  doc.setFillColor(r, g, b);
  doc.setDrawColor(r, g, b);
  const [first, ...rest] = points;
  const lines = rest.map((p, i) => {
    const prev = i === 0 ? first : rest[i - 1];
    return [p[0] - prev[0], p[1] - prev[1]];
  });
  doc.lines(lines, first[0], first[1], [1, 1], "F", true);
}

// Génère et télécharge le certificat officiel (naissance ou décès) au format PDF, avec un
// QR Code de vérification en bas de page — uniquement disponible pour un dossier « Validé ».
async function telechargerCertificatPDF(r, type, agentsDisponibles) {
  const [{ default: jsPDF }, { default: QRCode }] = await Promise.all([
    import("jspdf"),
    import("qrcode"),
  ]);
  const isNaissance = type === "naissance";
  const reference = r.id;
  const numDocument = genererNumeroDocument(r.commune, reference, r.region);
  const numInscription = genererNumeroInscription(reference);
  const officier = officierPourDossier(agentsDisponibles, reference, r.commune);
  const titreSignature = titreOfficier(officier.role, r.commune);
  const dateDelivrance = new Date().toISOString().slice(0, 10);

  // Le QR Code encode les éléments qui permettent à un tiers de vérifier l'authenticité du
  // document (numéro de document, numéro d'inscription, identité), à valider ultérieurement
  // auprès d'une API nationale de vérification — non implémentée dans ce prototype.
  const contenuVerification = versAsciiSur(
    [
      "SYNDEC-CAM - Certificat officiel",
      `Type : ${isNaissance ? "Naissance" : "Deces"}`,
      `No de document : ${numDocument}`,
      `No d'inscription : ${numInscription}`,
      `Nom : ${isNaissance ? `${r.prenomEnfant || ""} ${r.nomEnfant || ""}` : `${r.prenomDefunt || ""} ${r.nomDefunt || ""}`}`.trim(),
      `Commune : ${r.commune}`,
    ].join("\n")
  );
  const qrDataUrl = await QRCode.toDataURL(contenuVerification, { margin: 1, width: 220, color: { dark: "#0D3B47", light: "#FFFFFF" } });

  const doc = new jsPDF({ unit: "mm", format: "a5" });
  const pageWidth = doc.internal.pageSize.getWidth();

  // Bandeau tricolore camerounais
  doc.setFillColor(0, 122, 94); doc.rect(0, 0, pageWidth / 3, 22, "F");
  doc.setFillColor(206, 17, 38); doc.rect(pageWidth / 3, 0, pageWidth / 3, 22, "F");
  doc.setFillColor(252, 209, 22); doc.rect((2 * pageWidth) / 3, 0, pageWidth / 3, 22, "F");
  // Étoile à 5 branches dessinée vectoriellement (les polices standard de jsPDF ne couvrent pas
  // le caractère unicode ★, qui s'afficherait comme un glyphe incorrect).
  dessinerEtoile(doc, pageWidth / 2, 11, 5, 252, 209, 22);
  doc.setFontSize(6.5); doc.setTextColor(255, 255, 255); doc.setFont("helvetica", "bold");
  doc.text("République du Cameroun", pageWidth / 6, 13, { align: "center" });
  doc.setFontSize(6.5); doc.setFont("helvetica", "normal"); doc.text("Paix — Travail — Patrie", (5 * pageWidth) / 6, 13, { align: "center" });

  doc.setTextColor(20, 20, 20);
  doc.setFontSize(15); doc.setFont("helvetica", "bold");
  doc.text(isNaissance ? "Certificat de naissance" : "Certificat de décès", 8, 33);
  doc.setFontSize(8); doc.setFont("helvetica", "normal");
  doc.text(`N° de document : ${numDocument}`, pageWidth - 8, 33, { align: "right" });

  let y = 44;
  const ligne = (label, value, x) => {
    doc.setFontSize(7.5); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "italic");
    doc.text(label, x, y);
    doc.setFontSize(11); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "bold");
    doc.text(String(value || "—"), x, y + 5);
  };
  const col2 = pageWidth / 2 + 4;

  if (isNaissance) {
    ligne("Nom", r.nomEnfant, 8); ligne("Prénom(s)", r.prenomEnfant, col2); y += 12;
    ligne("Sexe", r.sexe, 8); y += 12;
    ligne("Lieu de naissance", r.lieu, 8); ligne("Date de naissance", r.dateNaissance, col2); y += 12;
    ligne("Père", r.nomPere, 8); ligne("Mère", r.nomMere, col2); y += 12;
  } else {
    ligne("Nom", r.nomDefunt, 8); ligne("Prénom(s)", r.prenomDefunt, col2); y += 12;
    ligne("Sexe", r.sexe, 8); y += 12;
    ligne("Lieu du décès", r.lieu, 8); ligne("Date du décès", r.dateDeces, col2); y += 12;
    ligne("Père", r.nomPere, 8); ligne("Mère", r.nomMere, col2); y += 12;
  }
  doc.setDrawColor(220, 220, 220); doc.line(8, y, pageWidth - 8, y); y += 8;
  ligne("Numéro d'inscription", numInscription, 8); ligne("Date de délivrance", dateDelivrance, col2); y += 14;

  doc.setFontSize(7); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "normal");
  doc.text(`Les renseignements reproduits sont conformes à ceux inscrits au registre de l'état civil de ${r.commune}.`, 8, y, { maxWidth: pageWidth - 60 });
  doc.setFont("helvetica", "bold"); doc.setTextColor(60, 60, 60);
  doc.text("Ce certificat n'est pas valide s'il est modifié ou plastifié.", 8, y + 5);

  doc.addImage(qrDataUrl, "PNG", pageWidth - 32, y - 14, 24, 24);
  doc.setFontSize(6); doc.setTextColor(140, 140, 140);
  doc.text("Scanner pour vérifier", pageWidth - 20, y + 12, { align: "center" });

  y += 22;
  doc.setDrawColor(180, 180, 180); doc.line(8, y, pageWidth - 8, y); y += 6;
  doc.setFontSize(7.5); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "italic");
  doc.text("Certifié conforme", 8, y);
  doc.text(titreSignature, pageWidth - 8, y, { align: "right" });
  y += 8;
  if (officier.signature) {
    // Signature électronique réelle (dessinée ou importée par l'officier) — insérée telle quelle,
    // au format détecté depuis l'en-tête de la donnée encodée (PNG pour un dessin, JPEG possible
    // pour une image importée).
    const formatImage = /^data:image\/jpe?g/i.test(officier.signature) ? "JPEG" : "PNG";
    try {
      doc.addImage(officier.signature, formatImage, pageWidth - 52, y - 9, 44, 16);
    } catch (erreurSignature) {
      // Donnée de signature invalide ou illisible : on se rabat sur le rendu stylisé par défaut
      // plutôt que d'interrompre la génération du certificat.
      doc.setFontSize(13); doc.setFont("helvetica", "bolditalic"); doc.setTextColor(20, 20, 20);
      doc.text(officier.nom, pageWidth - 8, y, { align: "right" });
    }
  } else {
    doc.setFontSize(13); doc.setFont("helvetica", "bolditalic"); doc.setTextColor(20, 20, 20);
    doc.text(officier.nom, pageWidth - 8, y, { align: "right" });
  }
  doc.setDrawColor(120, 120, 120); doc.line(pageWidth - 60, y + 2, pageWidth - 8, y + 2);
  doc.setFontSize(9); doc.setFont("helvetica", "bold");
  doc.text(officier.nom, pageWidth - 8, y + 7, { align: "right" });

  doc.save(`certificat_${isNaissance ? "naissance" : "deces"}_${reference}.pdf`);
}

/* ==================================================================
   Génération PDF — documents SYNGESE-CAM (Certificat de scolarité,
   Certificat de transfert, Bulletin de notes). Même bandeau tricolore
   et même style général que les certificats SYNDEC-CAM ci-dessus, pour
   une identité visuelle cohérente sur l'ensemble de la plateforme RTC.
   ================================================================== */
function dessinerEnteteDocumentSyngese(doc, titre, etablissement) {
  const pageWidth = doc.internal.pageSize.getWidth();
  doc.setFillColor(0, 122, 94); doc.rect(0, 0, pageWidth / 3, 22, "F");
  doc.setFillColor(206, 17, 38); doc.rect(pageWidth / 3, 0, pageWidth / 3, 22, "F");
  doc.setFillColor(252, 209, 22); doc.rect((2 * pageWidth) / 3, 0, pageWidth / 3, 22, "F");
  dessinerEtoile(doc, pageWidth / 2, 11, 5, 252, 209, 22);
  doc.setFontSize(6.5); doc.setTextColor(255, 255, 255); doc.setFont("helvetica", "bold");
  doc.text("République du Cameroun", pageWidth / 6, 13, { align: "center" });
  doc.setFontSize(6.5); doc.setFont("helvetica", "normal"); doc.text("Paix — Travail — Patrie", (5 * pageWidth) / 6, 13, { align: "center" });

  // Logo de l'établissement — celui propre à l'établissement s'il a été renseigné à sa création
  // (voir LogoField dans le formulaire), sinon le logo RTC par défaut (LOGO_BADGE_URI), pour que
  // chaque document généré porte toujours une image d'en-tête, jamais un espace vide.
  const logoAAfficher = etablissement?.logo || LOGO_BADGE_URI;
  try {
    const formatLogo = /^data:image\/jpe?g/i.test(logoAAfficher) ? "JPEG" : "PNG";
    doc.addImage(logoAAfficher, formatLogo, 8, 26, 12, 12);
  } catch (e) {
    // Une image corrompue ou dans un format non pris en charge par jsPDF ne doit jamais empêcher
    // la génération du reste du document — le nom de l'établissement seul suffit alors.
  }

  doc.setTextColor(20, 20, 20);
  doc.setFontSize(9); doc.setFont("helvetica", "bold");
  doc.text(etablissement?.nom || "", pageWidth / 2, 30, { align: "center" });
  doc.setFontSize(8); doc.setFont("helvetica", "normal"); doc.setTextColor(90, 90, 90);
  doc.text("SYNGESE-CAM — Système intégré de gestion du système éducatif", pageWidth / 2, 35, { align: "center" });

  doc.setDrawColor(180, 180, 180); doc.line(8, 39, pageWidth - 8, 39);
  doc.setTextColor(20, 20, 20); doc.setFontSize(14); doc.setFont("helvetica", "bold");
  doc.text(titre, pageWidth / 2, 48, { align: "center" });
  return pageWidth;
}

function dessinerPiedDocumentSyngese(doc, y, etablissement, directeur, directeurSignature) {
  const pageWidth = doc.internal.pageSize.getWidth();
  doc.setFontSize(7); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "normal");
  doc.text("Le présent document est délivré à la demande de l'intéressé(e), pour servir et valoir ce que de droit.", 8, y, { maxWidth: pageWidth - 16 });
  y += 12;
  doc.setDrawColor(180, 180, 180); doc.line(8, y, pageWidth - 8, y); y += 6;
  doc.setFontSize(7.5); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "italic");
  doc.text(`Fait le ${todayISO()}`, 8, y);
  doc.text("Le Directeur", pageWidth - 8, y, { align: "right" });
  y += 8;
  if (directeurSignature) {
    // Signature électronique réelle (dessinée ou importée par le Directeur, via SignatureField
    // sur la fiche établissement) — insérée telle quelle, au même titre que pour les certificats
    // SYNDEC-CAM, plutôt que le rendu stylisé par défaut.
    const formatImage = /^data:image\/jpe?g/i.test(directeurSignature) ? "JPEG" : "PNG";
    try {
      doc.addImage(directeurSignature, formatImage, pageWidth - 52, y - 9, 44, 16);
    } catch (erreurSignature) {
      // Donnée de signature invalide ou illisible : repli sur le rendu stylisé par défaut plutôt
      // que d'interrompre la génération du document.
      doc.setFontSize(13); doc.setFont("helvetica", "bolditalic"); doc.setTextColor(20, 20, 20);
      doc.text(directeur || "—", pageWidth - 8, y, { align: "right" });
    }
  } else {
    doc.setFontSize(13); doc.setFont("helvetica", "bolditalic"); doc.setTextColor(20, 20, 20);
    doc.text(directeur || "—", pageWidth - 8, y, { align: "right" });
  }
  y += 2;
  doc.setDrawColor(120, 120, 120); doc.line(pageWidth - 60, y, pageWidth - 8, y);
  doc.setFontSize(9); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "bold");
  doc.text(directeur || "—", pageWidth - 8, y + 5, { align: "right" });
}

/* ------------------------------------------------------------------
   Documents CAM-SMS — mêmes fonctions de dessin d'en-tête/pied de page
   que SYNGESE-CAM (bandeau tricolore, logo établissement avec repli
   RTC, signature électronique du Head Teacher / Principal), mais en
   anglais et sous le nom du module CAM-SMS, plutôt qu'une réutilisation
   directe des fonctions francophones qui mentionnent SYNGESE-CAM en dur.
   ------------------------------------------------------------------ */
function dessinerEnteteDocumentCamSms(doc, title, school) {
  const pageWidth = doc.internal.pageSize.getWidth();
  doc.setFillColor(0, 122, 94); doc.rect(0, 0, pageWidth / 3, 22, "F");
  doc.setFillColor(206, 17, 38); doc.rect(pageWidth / 3, 0, pageWidth / 3, 22, "F");
  doc.setFillColor(252, 209, 22); doc.rect((2 * pageWidth) / 3, 0, pageWidth / 3, 22, "F");
  dessinerEtoile(doc, pageWidth / 2, 11, 5, 252, 209, 22);
  doc.setFontSize(6.5); doc.setTextColor(255, 255, 255); doc.setFont("helvetica", "bold");
  doc.text("Republic of Cameroon", pageWidth / 6, 13, { align: "center" });
  doc.setFontSize(6.5); doc.setFont("helvetica", "normal"); doc.text("Peace — Work — Fatherland", (5 * pageWidth) / 6, 13, { align: "center" });

  const logoToShow = school?.logo || LOGO_BADGE_URI;
  try {
    const logoFormat = /^data:image\/jpe?g/i.test(logoToShow) ? "JPEG" : "PNG";
    doc.addImage(logoToShow, logoFormat, 8, 26, 12, 12);
  } catch (e) {
    // A corrupted or unsupported image must never block the rest of the document from
    // generating — the school name alone is enough in that case.
  }

  doc.setTextColor(20, 20, 20);
  doc.setFontSize(9); doc.setFont("helvetica", "bold");
  doc.text(school?.name || "", pageWidth / 2, 30, { align: "center" });
  doc.setFontSize(8); doc.setFont("helvetica", "normal"); doc.setTextColor(90, 90, 90);
  doc.text("CAM-SMS — Cameroon School Management System", pageWidth / 2, 35, { align: "center" });

  doc.setDrawColor(180, 180, 180); doc.line(8, 39, pageWidth - 8, 39);
  doc.setTextColor(20, 20, 20); doc.setFontSize(14); doc.setFont("helvetica", "bold");
  doc.text(title, pageWidth / 2, 48, { align: "center" });
  return pageWidth;
}

function dessinerPiedDocumentCamSms(doc, y, school, headTeacher, headTeacherSignature) {
  const pageWidth = doc.internal.pageSize.getWidth();
  doc.setFontSize(7); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "normal");
  doc.text("This document is issued at the request of the person concerned, to serve and be valid as required by law.", 8, y, { maxWidth: pageWidth - 16 });
  y += 12;
  doc.setDrawColor(180, 180, 180); doc.line(8, y, pageWidth - 8, y); y += 6;
  doc.setFontSize(7.5); doc.setTextColor(110, 110, 110); doc.setFont("helvetica", "italic");
  doc.text(`Issued on ${todayISO()}`, 8, y);
  doc.text("Head Teacher / Principal", pageWidth - 8, y, { align: "right" });
  y += 8;
  if (headTeacherSignature) {
    const imageFormat = /^data:image\/jpe?g/i.test(headTeacherSignature) ? "JPEG" : "PNG";
    try {
      doc.addImage(headTeacherSignature, imageFormat, pageWidth - 52, y - 9, 44, 16);
    } catch (signatureError) {
      doc.setFontSize(13); doc.setFont("helvetica", "bolditalic"); doc.setTextColor(20, 20, 20);
      doc.text(headTeacher || "—", pageWidth - 8, y, { align: "right" });
    }
  } else {
    doc.setFontSize(13); doc.setFont("helvetica", "bolditalic"); doc.setTextColor(20, 20, 20);
    doc.text(headTeacher || "—", pageWidth - 8, y, { align: "right" });
  }
  y += 2;
  doc.setDrawColor(120, 120, 120); doc.line(pageWidth - 60, y, pageWidth - 8, y);
  doc.setFontSize(9); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "bold");
  doc.text(headTeacher || "—", pageWidth - 8, y + 5, { align: "right" });
}

// Certificat de scolarité — atteste l'inscription régulière de l'élève dans sa classe pour
// l'année scolaire en cours.
async function telechargerCertificatScolaritePDF(eleve, classe, etablissement) {
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ unit: "mm", format: "a5" });
  const pageWidth = dessinerEnteteDocumentSyngese(doc, "Certificat de scolarité", etablissement);

  let y = 62;
  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`Le Directeur de l'établissement ${etablissement?.nom || "—"} certifie que :`, 8, y, { maxWidth: pageWidth - 16 });
  y += 12;
  doc.setFontSize(13); doc.setFont("helvetica", "bold");
  doc.text(`${eleve.prenom} ${eleve.nom}`, pageWidth / 2, y, { align: "center" });
  doc.setFontSize(8); doc.setFont("helvetica", "italic"); doc.setTextColor(90, 90, 90);
  doc.text(`Matricule ${eleve.matricule}`, pageWidth / 2, y + 5, { align: "center" });
  y += 16;

  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`né(e) le ${eleve.dateNaissance || "—"} à ${eleve.lieuNaissance || "—"},`, 8, y, { maxWidth: pageWidth - 16 });
  y += 10;
  doc.text(`est régulièrement inscrit(e) en classe de ${classe?.nom || "—"} pour l'année scolaire ${ANNEE_SCOLAIRE_COURANTE}, statut : ${eleve.statut}.`, 8, y, { maxWidth: pageWidth - 16 });
  y += 24;

  dessinerPiedDocumentSyngese(doc, y, etablissement?.nom, etablissement?.directeur, etablissement?.directeurSignature);
  doc.save(`certificat_scolarite_${eleve.matricule}.pdf`);
}

// Certificat de transfert — atteste la scolarité antérieure de l'élève, en vue d'une inscription
// dans un autre établissement.
async function telechargerCertificatTransfertPDF(eleve, classe, etablissement) {
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ unit: "mm", format: "a5" });
  const pageWidth = dessinerEnteteDocumentSyngese(doc, "Certificat de transfert", etablissement);

  let y = 62;
  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`Le Directeur de l'établissement ${etablissement?.nom || "—"} certifie que :`, 8, y, { maxWidth: pageWidth - 16 });
  y += 12;
  doc.setFontSize(13); doc.setFont("helvetica", "bold");
  doc.text(`${eleve.prenom} ${eleve.nom}`, pageWidth / 2, y, { align: "center" });
  doc.setFontSize(8); doc.setFont("helvetica", "italic"); doc.setTextColor(90, 90, 90);
  doc.text(`Matricule ${eleve.matricule}`, pageWidth / 2, y + 5, { align: "center" });
  y += 16;

  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`né(e) le ${eleve.dateNaissance || "—"} à ${eleve.lieuNaissance || "—"},`, 8, y, { maxWidth: pageWidth - 16 });
  y += 10;
  doc.text(`a été inscrit(e) en classe de ${classe?.nom || "—"} jusqu'au ${todayISO()}, et sollicite son transfert vers un autre établissement. Aucune sanction disciplinaire en cours ne s'oppose à ce transfert.`, 8, y, { maxWidth: pageWidth - 16 });
  y += 30;

  dessinerPiedDocumentSyngese(doc, y, etablissement?.nom, etablissement?.directeur, etablissement?.directeurSignature);
  doc.save(`certificat_transfert_${eleve.matricule}.pdf`);
}

// Attestation de réussite — déclare l'élève admis(e) en classe supérieure, à condition que sa
// moyenne générale soit suffisante (>= 10/20) ; sinon, la fonction refuse explicitement de
// délivrer le document plutôt que de générer une attestation trompeuse.
async function telechargerAttestationReussitePDF(eleve, classe, etablissement, bulletinData) {
  if (bulletinData.moyenneGenerale === null || bulletinData.moyenneGenerale < 10) {
    // Garde-fou : ne jamais délivrer une attestation de réussite à un élève dont la moyenne est
    // insuffisante ou non renseignée, même si le bouton a été cliqué par erreur.
    return { ok: false, message: "Moyenne générale insuffisante ou non renseignée — cette attestation ne peut être délivrée en l'état." };
  }
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ unit: "mm", format: "a5" });
  const pageWidth = dessinerEnteteDocumentSyngese(doc, "Attestation de réussite", etablissement);

  let y = 62;
  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`Le Directeur de l'établissement ${etablissement?.nom || "—"} certifie que :`, 8, y, { maxWidth: pageWidth - 16 });
  y += 12;
  doc.setFontSize(13); doc.setFont("helvetica", "bold");
  doc.text(`${eleve.prenom} ${eleve.nom}`, pageWidth / 2, y, { align: "center" });
  doc.setFontSize(8); doc.setFont("helvetica", "italic"); doc.setTextColor(90, 90, 90);
  doc.text(`Matricule ${eleve.matricule}`, pageWidth / 2, y + 5, { align: "center" });
  y += 16;

  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`né(e) le ${eleve.dateNaissance || "—"} à ${eleve.lieuNaissance || "—"},`, 8, y, { maxWidth: pageWidth - 16 });
  y += 10;
  doc.text(`a obtenu une moyenne générale de`, 8, y, { maxWidth: pageWidth - 16 });
  y += 7;
  doc.setFontSize(13); doc.setFont("helvetica", "bold"); doc.setTextColor(63, 167, 114);
  doc.text(`${bulletinData.moyenneGenerale.toFixed(2)} / 20`, pageWidth / 2, y, { align: "center" });
  y += 10;
  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "normal");
  doc.text(`pour l'année scolaire ${ANNEE_SCOLAIRE_COURANTE} et est déclaré(e) admis(e) en classe de ${classe?.nom || "—"}.`, 8, y, { maxWidth: pageWidth - 16 });
  y += 24;

  dessinerPiedDocumentSyngese(doc, y, etablissement?.nom, etablissement?.directeur, etablissement?.directeurSignature);
  doc.save(`attestation_reussite_${eleve.matricule}.pdf`);
  return { ok: true };
}

// Bulletin de notes — identité de l'élève, classe, année scolaire, notes détaillées par matière
// avec coefficients et moyennes, moyenne générale, absences, conforme au cahier des charges,
// section 3.9 (contenu du bulletin).
async function telechargerBulletinPDF(eleve, classe, etablissement, bulletinData) {
  const { default: jsPDF } = await import("jspdf");
  const doc = new jsPDF({ unit: "mm", format: "a4" });
  const pageWidth = dessinerEnteteDocumentSyngese(doc, "Bulletin de notes", etablissement);

  let y = 58;
  doc.setFontSize(10); doc.setTextColor(20, 20, 20); doc.setFont("helvetica", "bold");
  doc.text(`${eleve.prenom} ${eleve.nom}`, 8, y);
  doc.setFont("helvetica", "normal"); doc.setTextColor(90, 90, 90); doc.setFontSize(8);
  doc.text(`Matricule ${eleve.matricule}`, 8, y + 5);
  doc.setTextColor(20, 20, 20); doc.setFontSize(10); doc.setFont("helvetica", "bold");
  doc.text(`Classe : ${classe?.nom || "—"}`, pageWidth - 8, y, { align: "right" });
  doc.setFont("helvetica", "normal"); doc.setTextColor(90, 90, 90); doc.setFontSize(8);
  doc.text(`Année scolaire ${ANNEE_SCOLAIRE_COURANTE}`, pageWidth - 8, y + 5, { align: "right" });
  y += 14;

  doc.setDrawColor(180, 180, 180); doc.line(8, y, pageWidth - 8, y); y += 8;

  // En-tête du tableau des matières
  doc.setFontSize(8); doc.setFont("helvetica", "bold"); doc.setTextColor(90, 90, 90);
  doc.text("Matière", 8, y); doc.text("Coeff.", 100, y); doc.text("Notes", 125, y); doc.text("Moyenne", pageWidth - 8, y, { align: "right" });
  y += 3;
  doc.setDrawColor(150, 150, 150); doc.line(8, y, pageWidth - 8, y); y += 6;

  doc.setFont("helvetica", "normal"); doc.setTextColor(20, 20, 20); doc.setFontSize(9);
  if (bulletinData.moyennesParMatiere.length === 0) {
    doc.setFont("helvetica", "italic"); doc.setTextColor(140, 140, 140);
    doc.text("Aucune évaluation enregistrée pour cette année scolaire.", 8, y);
    y += 8;
  } else {
    bulletinData.moyennesParMatiere.forEach((m) => {
      doc.setFont("helvetica", "normal"); doc.setTextColor(20, 20, 20);
      doc.text(m.matiere, 8, y);
      doc.text(String(m.coefficient), 100, y);
      doc.text(String(m.nbNotes), 125, y);
      doc.setFont("helvetica", "bold");
      const [cr1, cg1, cb1] = m.moyenne >= 10 ? [63, 167, 114] : [210, 72, 62];
      doc.setTextColor(cr1, cg1, cb1);
      doc.text(`${m.moyenne.toFixed(2)} / 20`, pageWidth - 8, y, { align: "right" });
      y += 7;
    });
  }

  y += 4;
  doc.setDrawColor(150, 150, 150); doc.line(8, y, pageWidth - 8, y); y += 8;
  doc.setFontSize(11); doc.setFont("helvetica", "bold"); doc.setTextColor(20, 20, 20);
  doc.text("Moyenne générale", 8, y);
  const [cr2, cg2, cb2] = bulletinData.moyenneGenerale !== null && bulletinData.moyenneGenerale >= 10 ? [63, 167, 114] : [210, 72, 62];
  doc.setTextColor(cr2, cg2, cb2);
  doc.text(bulletinData.moyenneGenerale !== null ? `${bulletinData.moyenneGenerale.toFixed(2)} / 20` : "—", pageWidth - 8, y, { align: "right" });
  y += 10;

  doc.setFontSize(9); doc.setFont("helvetica", "normal"); doc.setTextColor(90, 90, 90);
  doc.text(`Absences non justifiées : ${bulletinData.nbAbsences}`, 8, y);
  y += 16;

  dessinerPiedDocumentSyngese(doc, y, etablissement?.nom, etablissement?.directeur, etablissement?.directeurSignature);
  doc.save(`bulletin_${eleve.matricule}_${ANNEE_SCOLAIRE_COURANTE.replace("/", "-")}.pdf`);
}

