// Le matricule d'un employé du RTC est toujours une chaîne de 4 caractères (0001, 0002…),
// distincte de l'identifiant technique EMP-XXXX. Les dossiers enregistrés avant son
// introduction n'en portaient aucun — d'où la colonne vide affichée dans le Pilotage RH : cette
// normalisation en attribue un à la volée au chargement, en repartant du plus grand déjà pris,
// et reprend au passage l'ancien champ noEmploye s'il traîne encore dans les données stockées.
function normaliserMatriculesEmployes(liste) {
  if (!Array.isArray(liste)) return liste;
  let maxi = Math.max(0, ...liste.map((e) => parseInt(e?.matricule || e?.noEmploye || "0", 10) || 0));
  return liste.map((e) => {
    const existant = e?.matricule || e?.noEmploye;
    const { noEmploye, ...reste } = e || {};
    return { ...reste, matricule: existant ? String(existant).trim().padStart(4, "0").slice(-4) : String(++maxi).padStart(4, "0") };
  });
}

