/* --- Matrices du tableau de bord --- */
const WEEKDAYS = ["Lun", "Mar", "Mer", "Jeu", "Ven", "Sam", "Dim"];
const MONTHS = ["Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Août", "Sep", "Oct", "Nov", "Déc"];

// Indicateurs hebdomadaires (démonstration) : nb. d'événements par jour de la semaine.
// Règle de calcul conforme au complément SSRN : Incident et Accident sont deux classifications
// distinctes et mutuellement exclusives d'un signalement (jamais additionnées) ; on a donc toujours
// Incidents + Accidents ≤ Signalements (le solde correspond aux fausses alertes, doublons et signalements
// non encore classés). Blessés et Décès sont dérivés du nombre d'Accidents (victimes), pas générés à part.
const weeklyMatrix = [
  { label: "Signalements", values: [12, 9, 14, 11, 18, 22, 15] },
  { label: "Recherches & enquêtes", values: [5, 4, 6, 5, 8, 10, 6] },
  { label: "Incidents", values: [6, 5, 7, 6, 9, 11, 8] },
  { label: "Accidents", values: [2, 1, 3, 2, 4, 5, 3] },
  { label: "Blessés", values: [4, 2, 6, 4, 8, 10, 6] },
  { label: "Décès", values: [0, 0, 1, 0, 1, 1, 1] },
];

// Génération déterministe de la matrice mensuelle : 12 mois en ligne, indicateurs en colonne.
// Mêmes règles que la matrice hebdomadaire : Incident et Accident sont deux classifications distinctes
// (jamais additionnées) et Incidents + Accidents ≤ Signalements ; Blessés et Décès sont dérivés du
// nombre d'Accidents du mois plutôt que générés indépendamment.
const INDICATOR_COLUMNS = ["Signalements", "Recherches & enquêtes", "Incidents", "Accidents", "Blessés", "Décès"];
function seededFrac(seed) { const x = Math.sin(seed) * 10000; return x - Math.floor(x); }
function buildMonthlyIndicatorMatrix(annee = new Date().getFullYear()) {
  const monthFactor = [0.9, 0.85, 0.95, 1.05, 1.1, 0.9, 0.85, 0.9, 1, 1.1, 1.2, 1.45]; // pic décembre (fêtes)
  const base = { signalements: 150, recherches: 60, incidents: 68, accidents: 28 };
  return MONTHS.map((m, mi) => {
    const f = monthFactor[mi];
    const noise = (seed) => Math.floor(seededFrac(annee * 97 + mi * 13 + seed) * 8);
    const signalements = Math.round(base.signalements * f) + noise(1);
    const recherches = Math.round(base.recherches * f) + noise(2);
    const accidents = Math.max(0, Math.round(base.accidents * f) + noise(3) - 4);
    // Incidents : classification indépendante des accidents, plafonnée pour garantir Incidents + Accidents ≤ Signalements
    const incidentsBruts = Math.max(0, Math.round(base.incidents * f) + noise(4) - 4);
    const incidents = Math.min(incidentsBruts, Math.max(0, signalements - accidents));
    // Blessés et décès dérivés du nombre d'accidents du mois (≈2,1 blessés et ≈0,15 décès par accident), pas générés à part
    const blesses = Math.max(0, Math.round(accidents * 2.1) + noise(5) - 4);
    const deces = Math.max(0, Math.round(accidents * 0.15 + seededFrac(annee * 61 + mi + 50)));
    return { label: m, values: [signalements, recherches, incidents, accidents, blesses, deces] };
  });
}
const monthlyIndicatorMatrix = buildMonthlyIndicatorMatrix();

// Répartition annuelle (somme des 12 mois) des indicateurs de sécurité, pour le camembert du tableau de bord
const INDICATOR_COLORS = ["#E8A33D", "#1E8FA6", "#D2483E", "#B23A31", "#5B7C86", "#8A2E2E"];
function buildIndicatorsPieData(annee = new Date().getFullYear()) {
  const matrice = buildMonthlyIndicatorMatrix(annee);
  return INDICATOR_COLUMNS.map((label, i) => ({
    name: label,
    value: matrice.reduce((sum, row) => sum + row.values[i], 0),
    color: INDICATOR_COLORS[i],
  }));
}

