// Aléa cryptographique. Math.random() n'est pas un générateur sûr : V8 l'implémente avec
// xorshift128+, dont l'état interne se reconstitue à partir de quelques sorties observées — or
// les identifiants générés sont affichés en clair dans presque toutes les tables. Tout secret
// dérivé du même générateur (mot de passe temporaire, clé API) en devenait prédictible.
function aleaCrypto(n) {
  const t = new Uint32Array(n);
  if (typeof crypto !== "undefined" && crypto.getRandomValues) crypto.getRandomValues(t);
  else for (let i = 0; i < n; i++) t[i] = Math.floor(Math.random() * 4294967296); // repli extrême
  return t;
}
function chaineAleatoire(longueur, alphabet) {
  const t = aleaCrypto(longueur);
  let s = "";
  for (let i = 0; i < longueur; i++) s += alphabet[t[i] % alphabet.length];
  return s;
}
// 8 caractères sur un alphabet de 32 → ~40 bits, contre 13 bits auparavant (9 000 valeurs, où
// une collision devenait probable dès une centaine d'enregistrements). C'était une faille
// d'identité et pas seulement de qualité : session.userId est la seule clé de session, et toutes
// les résolutions de compte se font par find() — deux comptes partageant un identifiant faisaient
// hériter l'un des droits de l'autre.
const genId = (prefix) => `${prefix}-${chaineAleatoire(8, "ABCDEFGHJKLMNPQRSTUVWXYZ23456789")}`;

// Préfixe d'identifiant des agents habilités de l'état civil (écran « Officier d'état civil &
// Maire ») : l'ID d'un agent porte toujours le code de son rôle, de sorte que le rôle se lise
// directement dans la référence du dossier — OEC-xxxx pour un Officier d'état civil, SEC-xxxx
// pour un Secrétaire d'état civil, AAM-xxxx pour un Adjoint au maire, MAI-xxxx pour un Maire.
const PREFIXE_ID_AGENT_EC = {
  "Officier d'état civil": "OEC",
  "Secrétaire d'état civil": "SEC",
  "Adjoint au maire": "AAM",
  "Maire": "MAI",
};
// Rôle inconnu (profil ajouté ultérieurement au catalogue) → repli sur OEC, jamais d'erreur.
const prefixeIdAgentEC = (role) => PREFIXE_ID_AGENT_EC[role] || "OEC";
// Réaligne l'ID d'un agent existant sur son (nouveau) rôle en conservant sa partie numérique,
// ex. « OEC-002 » requalifié en Secrétaire d'état civil devient « SEC-002 ».
function idAgentECPourRole(idActuel, role) {
  const prefixe = prefixeIdAgentEC(role);
  const numero = String(idActuel || "").split("-").slice(1).join("-");
  return numero ? `${prefixe}-${numero}` : genId(prefixe);
}

// Validation du format téléphonique camerounais : 9 chiffres commençant par 6 (tous opérateurs
// mobiles camerounais depuis l'unification du plan de numérotation), espaces optionnelles
// tolérées à la saisie (ex. « 6 55 12 34 56 », « 655123456 »).
const REGEX_TEL_CM = /^6\d{8}$/;
function telephoneCMValide(valeur) {
  if (!valeur) return false;
  return REGEX_TEL_CM.test(String(valeur).replace(/\s+/g, ""));
}
// Validation du format de pièce d'identité camerounaise (CNI) : 9 chiffres, conformément au
// format observé dans les dossiers du module (ex. « 108245XXX »).
const REGEX_CNI_CM = /^\d{9}$/;
function cniValide(valeur) {
  if (!valeur) return false;
  return REGEX_CNI_CM.test(String(valeur).replace(/\s+/g, ""));
}
// Pour les champs acceptant indifféremment un e-mail ou un numéro de téléphone (identifiants de
// connexion) : valide si l'un des deux formats est respecté.
function emailOuTelephoneCMValide(valeur) {
  if (!valeur) return false;
  const v = String(valeur).trim();
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v) || telephoneCMValide(v);
}
