const FEE_PURPOSES_CAM_SMS = ["Registration fee", "School fees", "Transport fee", "Feeding fee", "Examination fee", "Uniform fee", "Other fees"];
const PAYMENT_METHODS_CAM_SMS = ["Cash", "Bank transfer", "Mobile Money", "Online payment", "Cheque"];
const seedFeePaymentsCamSms = [
  { id: "FEE-0001", learnerId: "LRN-0001", payer: "Ojong Peter", amount: 60000, currency: "FCFA", purpose: "School fees", date: "2026-09-05", paymentMethod: "Mobile Money", reference: "MTN-77213045", status: "Paid" },
  { id: "FEE-0002", learnerId: "LRN-0002", payer: "Ndifor Mercy", amount: 25000, currency: "FCFA", purpose: "Registration fee", date: "2026-09-08", paymentMethod: "Cash", reference: "", status: "Paid" },
];

