            const regionsAvailable = [...new Set(schoolsForIndicators.map((s) => s.region))].sort();
            const divisionsAvailable = [...new Set(schoolsForIndicators.filter((s) => !statsFiltreRegion || s.region === statsFiltreRegion).map((s) => s.division))].sort();
            const subdivisionsAvailable = [...new Set(schoolsForIndicators.filter((s) => !statsFiltreDivision || s.division === statsFiltreDivision).map((s) => s.subdivision))].sort();
            const schoolsAvailable = schoolsForIndicators.filter((s) =>
              (!statsFiltreRegion || s.region === statsFiltreRegion) &&
              (!statsFiltreDivision || s.division === statsFiltreDivision) &&
              (!statsFiltreSubdivision || s.subdivision === statsFiltreSubdivision)
            );
            // Options construites sur les classes du périmètre : la liste sortait auparavant du
            // tableau brut, exposant « Form 3 » à un utilisateur en Primary et inversement.
