/* ==================================================================================
   PILOTAGE RH — Feuilles de temps & Gestion des congés et absences
   ----------------------------------------------------------------------------------
   Deux modules greffés sur le volet « Pilotage RH » de SYNSR-CAM, adossés au
   référentiel existant du Personnel du RTC (le matricule sur 4 caractères sert de
   clé de rattachement, exactement comme le prévoit le cahier des charges).

   Convention structurante : LA SEMAINE DE TRAVAIL DU RTC COURT DU SAMEDI AU
   VENDREDI. Toutes les périodes hebdomadaires, l'affichage de la grille de saisie
   et le calcul des heures supplémentaires en découlent.
   ================================================================================== */

// Ordre d'affichage des colonnes de la grille de saisie — samedi en tête.
const JOURS_SEMAINE_RTC = ["Samedi", "Dimanche", "Lundi", "Mardi", "Mercredi", "Jeudi", "Vendredi"];

// Formatage local (et non UTC) : passer par toISOString() décalerait la date d'un jour
// pour tout fuseau à l'ouest de Greenwich, ce qui ferait glisser les semaines.
function isoLocalRH(d) {
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}
function ajouterJoursRH(iso, n) {
  const d = new Date(`${iso}T00:00:00`);
  d.setDate(d.getDate() + n);
  return isoLocalRH(d);
}
// Samedi de la semaine contenant la date donnée. getDay() : dimanche=0 … samedi=6,
// donc (jour + 1) % 7 donne le nombre de jours écoulés depuis le samedi.
function debutSemaineRTC(iso) {
  const d = new Date(`${iso}T00:00:00`);
  return ajouterJoursRH(iso, -((d.getDay() + 1) % 7));
}
function jourDeLaSemaineRH(iso) {
  return new Date(`${iso}T00:00:00`).getDay();
}
function formatJourRH(iso) {
  const d = new Date(`${iso}T00:00:00`);
  return `${String(d.getDate()).padStart(2, "0")}/${String(d.getMonth() + 1).padStart(2, "0")}`;
}
function formatDateLongueRH(iso) {
  if (!iso) return "—";
  const d = new Date(`${iso}T00:00:00`);
  const mois = ["janvier", "février", "mars", "avril", "mai", "juin", "juillet", "août", "septembre", "octobre", "novembre", "décembre"];
  return `${d.getDate()} ${mois[d.getMonth()]} ${d.getFullYear()}`;
}
function joursDeLaPeriodeRH(periode) {
  return Array.from({ length: 7 }, (_, i) => ajouterJoursRH(periode.debut, i));
}
function libellePeriodeRH(periode) {
  return `Sem. du ${formatJourRH(periode.debut)} au ${formatJourRH(periode.fin)}`;
}

/* --- Référentiel projets / tâches (imputation des heures) -------------------------- */
